insert into public.event_clues(event_id,difficulty,clue_text) values((select id from public.historical_events where slug='wikidata-q1052780'),'medium','This event is a significant moment in history. Study its people, timing, and setting.') on conflict(event_id,difficulty) do update set clue_text=excluded.clue_text;
insert into public.event_clues(event_id,difficulty,clue_text) values((select id from public.historical_events where slug='wikidata-q1052780'),'hard','This event is a significant moment in history. Study its people, timing, and setting.') on conflict(event_id,difficulty) do update set clue_text=excluded.clue_text;
insert into public.event_sources(event_id,url,title,accessed_at,editorial_status) values((select id from public.historical_events where slug='wikidata-q1052780'),'https://www.wikidata.org/wiki/Q1052780','Sherman''s March to the Sea — reference','2026-09-15','needs_review') on conflict(event_id,url) do nothing;
